class Solution {
public:
    int minChanges(vector<int>& nums, int k) {
        const int B = 1024, INF = 1 << 29;
        int n = nums.size();
        vector<int> dp(B, 0), tmp(B), cnt(B, 0);
        vector<pair<int,int>> pv;
        pv.reserve(n);
        int minAll = 0;
        for (int j = 0; j < k; ++j) {
            int m = 0;
            pv.clear();
            for (int i = j; i < n; i += k) { cnt[nums[i]]++; m++; }
            for (int i = j; i < n; i += k) {
                if (cnt[nums[i]] > 0) {
                    pv.push_back({nums[i], cnt[nums[i]]});
                    cnt[nums[i]] = 0;
                }
            }
            if (j == 0) {
                for (int x = 0; x < B; ++x) dp[x] = m;
                int mx = 0;
                for (auto& pr : pv) {
                    dp[pr.first] = m - pr.second;
                    if (pr.second > mx) mx = pr.second;
                }
                minAll = m - mx;
            } else {
                for (int x = 0; x < B; ++x) tmp[x] = INF;
                for (auto& pr : pv) {
                    int v = pr.first, c = pr.second;
                    for (int x = 0; x < B; ++x) {
                        int t = dp[x ^ v] - c;
                        if (t < tmp[x]) tmp[x] = t;
                    }
                }
                int minTmp = INF;
                for (int x = 0; x < B; ++x) if (tmp[x] < minTmp) minTmp = tmp[x];
                for (int x = 0; x < B; ++x) dp[x] = min(minAll, tmp[x]) + m;
                minAll = min(minAll, minTmp) + m;
            }
        }
        return dp[0];
    }
};
